const horario = '07h30';

const novo = horario.replace('h', ':');
console.log(`Saída do ônibus: ${novo}`);

const codigo = '789-1234-5678-9';

console.log(`Com replace: ${codigo.replace('-', '')}`);
console.log(`Com replaceAll: ${codigo.replaceAll('-', '')}`);

let telefone = '(81) 99876-5432';

telefone = telefone.replace('(', '');
telefone = telefone.replace(')', '');
telefone = telefone.replace(' ', '');
telefone = telefone.replace('-', '');

console.log(`Telefone: ${telefone}`);
console.log(`Dígitos: ${telefone.length}`);

